//! Desktop binary: calls the `run()` entry point generated by `frus::main!` in the
//! library. (On Android/Web there is no binary: the entry point is `android_main` /
//! `start`, both also generated by the macro.)
//!
//! `cargo run`; the log is on the console.

// A Windows release build is a windowed program, as an installed application is: no
// console opens beside it. A debug build keeps its console, and the log in it.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

#[cfg(not(any(target_os = "android", target_arch = "wasm32")))]
fn main() -> frus::anyhow::Result<()> {
    {{crate_name}}::run()
}

#[cfg(any(target_os = "android", target_arch = "wasm32"))]
fn main() {}
